package com.narudzbine.identity.infrastructure.web;
import jakarta.servlet.http.HttpServletRequest;
import java.io.IOException;
import java.util.*;
import tools.jackson.databind.json.JsonMapper;
final class StockRequests {
 private static final JsonMapper JSON=JsonMapper.builder().build();
 static Input input(HttpServletRequest request,boolean delta)throws IOException{var fields=delta?Set.of("delta","reason"):Set.of("expectedRevision","availableCount","reason");var b=AuthRequests.object(request,fields);for(String field:fields){if(!b.has(field)){throw new AuthHttpFailure(422,"VALIDATION_FAILED","/"+field);}}String field=delta?"delta":"availableCount";var n=b.path(field);int count;try{if(!n.isNumber()||!n.toString().matches(delta?"-?(0|[1-9][0-9]{0,9})":"0|[1-9][0-9]{0,9}")){throw new IllegalArgumentException();}long value=Long.parseLong(n.toString());if(value<(delta?-1000000000L:0)||value>1000000000){throw new IllegalArgumentException();}count=(int)value;}catch(IllegalArgumentException e){throw new AuthHttpFailure(422,"VALIDATION_FAILED","/"+field);}String reason=null;if(!b.path("reason").isNull()){var errors=new ArrayList<AuthErrors.FieldError>();reason=OrganizationRequests.text(b,"reason","",1000,false,errors);if(!errors.isEmpty()){throw new AuthHttpFailure(errors);}}return new Input(delta?null:ContactRequests.revision(b),count,reason);}
 static UUID key(HttpServletRequest r){var values=Collections.list(r.getHeaders("Idempotency-Key"));if(values.size()!=1||!values.getFirst().matches("[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}")){throw new AuthHttpFailure(List.of(new AuthErrors.FieldError("HEADER","Idempotency-Key","INVALID_VALUE")));}return UUID.fromString(values.getFirst());}
 static Query query(HttpServletRequest r){for(var e:r.getParameterMap().entrySet()){if(!Set.of("size","cursor","productId").contains(e.getKey())||e.getValue().length!=1){throw invalid(e.getKey());}}int size=25;try{String s=r.getParameter("size");if(s!=null){if(!s.matches("[1-9][0-9]{0,2}")){throw new IllegalArgumentException();}size=Integer.parseInt(s);if(size>100){throw new IllegalArgumentException();}}}catch(IllegalArgumentException e){throw invalid("size");}String cursor=r.getParameter("cursor");if(cursor!=null&&(cursor.isEmpty()||cursor.length()>2048)){throw invalid("cursor");}String p=r.getParameter("productId");return new Query(size,cursor,p==null?null:ContactRequests.id(p,"QUERY","productId"));}
 static byte[] digest(String domain,byte[] key,Object... values){try{var mac=javax.crypto.Mac.getInstance("HmacSHA256");mac.init(new javax.crypto.spec.SecretKeySpec(key,"HmacSHA256"));mac.update(("narudzbine/stock/"+domain+"/v1\0").getBytes(java.nio.charset.StandardCharsets.US_ASCII));return mac.doFinal(JSON.writeValueAsBytes(values));}catch(java.security.GeneralSecurityException e){throw new IllegalStateException("Stock fingerprint unavailable.");}}
 static AuthHttpFailure invalid(String field){return new AuthHttpFailure(List.of(new AuthErrors.FieldError("QUERY",field,"INVALID_VALUE")));}
 record Input(String expected,int quantity,String reason){@Override public String toString(){return "StockInput[redacted]";}}
 record Query(int size,String cursor,UUID product){}
}
